window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9e2a5660dfcf5c46"]={"versions": [{"id": "FIG-9e2a5660dfcf5c46", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung der interruptgesteuerten Sende-Bestätigung (Transmit Confirmation) im AUTOSAR Classic Platform Kommunikations-Stack (Schichten CAN Controller Hardware/Peripheral, MCAL CAN Driver, CAN Interface und CAN Interface User wie PduR, CanNm, CanTp).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Instanzen (von rechts nach links):</p>\n<ul class=\"fig-list\"><li><code>CanController</code> («Peripheral»): Hardware-Controller für CAN.\n</li><li><code>Can</code> («module»): MCAL-Treiber (CAN Driver) mit Dekompositionsindikator/Zersetzungssymbol.\n</li><li><code>CanIf</code> («module»): CAN-Interface-Modul.\n</li><li><code>CanIf User</code>: Generische obere Softwareschicht (z. B. PduR, CanNm, CanTp).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen/Aufrufe:</p>\n<ul class=\"fig-list\"><li><code>Transmit Interrupt()</code>: Hardware-/ISR-Ereignis vom Controller an den CAN-Treiber.\n</li><li><code>CanIf_TxConfirmation(PduIdType)</code>: Aufruf der Bestätigungs-Callback-Funktion im CAN Interface mit Angabe der PDU-ID.\n</li><li><code>&lt;User_TxConfirmation&gt;(PduIdType)</code>: Konfigurierbarer Callback an die obere Schicht (CanIf User) mit Übergabe der PDU-ID.\n</li><li>Assoziierte Rückkehrpfade (<code>&lt;User_TxConfirmation&gt;()</code>, <code>CanIf_TxConfirmation()</code>, <code>Transmit Interrupt()</code>) als gestrichelte Pfeile.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>CanController</code> löst nach erfolgreichem Sendevorgang einen Sende-Interrupt aus (<code>Transmit Interrupt()</code>), der den Kontext der Ausführungsleiste im Treiber <code>Can</code> aktiviert.\n</li><li>Der CAN-Treiber ruft synchron <code>CanIf_TxConfirmation(PduIdType)</code> am Modul <code>CanIf</code> auf.\n</li><li><code>CanIf</code> leitet die Bestätigung synchron über den typspezifisch konfigurierten Callback <code>&lt;User_TxConfirmation&gt;(PduIdType)</code> an den zuständigen <code>CanIf User</code> weiter.\n</li><li>Nach Abarbeitung im <code>CanIf User</code> kehrt der Aufruf über <code>&lt;User_TxConfirmation&gt;()</code> zu <code>CanIf</code> zurück.\n</li><li><code>CanIf</code> schließt seine Ausführung ab und kehrt über <code>CanIf_TxConfirmation()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Interrupt-Kontext wird abgeschlossen (<code>Transmit Interrupt()</code>-Rückkehr zum Controller).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert den synchronen Benachrichtigungspfad im Interrupt-Kontext: Sende-Bestätigungen bei aktivierter Interrupt-Steuerung erfordern die verzögerungsfreie Weiterleitung von der Hardware bis zum Zielmodul (<code>CanIf User</code>), sofern kein Polling konfiguriert ist. Treiber- und Interface-Implementierungen müssen sicherstellen, dass die Übergabe der <code>PduIdType</code> konsistent durchgereicht wird und Callbacks im Interrupt-Kontext nicht blockieren.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-460b7caf5ac43b12", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung der interruptgesteuerten Sende-Bestätigung (Transmit Confirmation) im AUTOSAR Classic Platform Kommunikations-Stack (Schichten CAN Controller Hardware/Peripheral, MCAL CAN Driver, CAN Interface und CAN Interface User wie PduR, CanNm, CanTp).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Teilnehmende Instanzen (von rechts nach links):</p>\n<ul class=\"fig-list\"><li><code>CanController</code> («Peripheral»): Hardware-Controller für CAN.\n</li><li><code>Can</code> («module»): MCAL-Treiber (CAN Driver) mit Dekompositionsindikator/Zersetzungssymbol.\n</li><li><code>CanIf</code> («module»): CAN-Interface-Modul.\n</li><li><code>CanIf User</code>: Generische obere Softwareschicht (z. B. PduR, CanNm, CanTp).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen/Aufrufe:</p>\n<ul class=\"fig-list\"><li><code>Transmit Interrupt()</code>: Hardware-/ISR-Ereignis vom Controller an den CAN-Treiber.\n</li><li><code>CanIf_TxConfirmation(PduIdType)</code>: Aufruf der Bestätigungs-Callback-Funktion im CAN Interface mit Angabe der PDU-ID.\n</li><li><code>&lt;User_TxConfirmation&gt;(PduIdType)</code>: Konfigurierbarer Callback an die obere Schicht (CanIf User) mit Übergabe der PDU-ID.\n</li><li>Assoziierte Rückkehrpfade (<code>&lt;User_TxConfirmation&gt;()</code>, <code>CanIf_TxConfirmation()</code>, <code>Transmit Interrupt()</code>) als gestrichelte Pfeile.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>CanController</code> löst nach erfolgreichem Sendevorgang einen Sende-Interrupt aus (<code>Transmit Interrupt()</code>), der den Kontext der Ausführungsleiste im Treiber <code>Can</code> aktiviert.\n</li><li>Der CAN-Treiber ruft synchron <code>CanIf_TxConfirmation(PduIdType)</code> am Modul <code>CanIf</code> auf.\n</li><li><code>CanIf</code> leitet die Bestätigung synchron über den typspezifisch konfigurierten Callback <code>&lt;User_TxConfirmation&gt;(PduIdType)</code> an den zuständigen <code>CanIf User</code> weiter.\n</li><li>Nach Abarbeitung im <code>CanIf User</code> kehrt der Aufruf über <code>&lt;User_TxConfirmation&gt;()</code> zu <code>CanIf</code> zurück.\n</li><li><code>CanIf</code> schließt seine Ausführung ab und kehrt über <code>CanIf_TxConfirmation()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Interrupt-Kontext wird abgeschlossen (<code>Transmit Interrupt()</code>-Rückkehr zum Controller).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert den synchronen Benachrichtigungspfad im Interrupt-Kontext: Sende-Bestätigungen bei aktivierter Interrupt-Steuerung erfordern die verzögerungsfreie Weiterleitung von der Hardware bis zum Zielmodul (<code>CanIf User</code>), sofern kein Polling konfiguriert ist. Treiber- und Interface-Implementierungen müssen sicherstellen, dass die Übergabe der <code>PduIdType</code> konsistent durchgereicht wird und Callbacks im Interrupt-Kontext nicht blockieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9e2a5660dfcf5c46", "to": "FIG-460b7caf5ac43b12", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
